 void mouseDown(const juce::MouseEvent&e)override{endDrag();if(!graph.contains(e.position))return;saveUndo();float nearest=1e9f;for(int i=0;i<12;++i){auto b=prefix()+juce::String(i)+"_";float d=e.position.getDistanceSquaredFrom(marker(i));if(d<nearest){nearest=d;selected=i;}}node.setSelectedId(selected+1,juce::sendNotificationSync);dragging=true;dragNode=selected;dragShape=int(p.value(nodeId("shape")));if(GraphModel::frequency(dragShape)){dragFrequency=p.state.getParameter(nodeId("freq"));dragFrequency->beginChangeGesture();}if(GraphModel::gain(dragShape)){dragGain=p.state.getParameter(nodeId("gain"));dragGain->beginChangeGesture();}mouseDrag(e);}
 void mouseDrag(const juce::MouseEvent&e)override{if(!dragging)return;if(selected!=dragNode||int(p.value(nodeId("shape")))!=dragShape){endDrag();return;}if(dragFrequency)p.set(nodeId("freq"),GraphModel::effectiveFrequency(20*std::pow(1000.f,juce::jlimit(0.f,1.f,(e.position.x-graph.getX())/graph.getWidth())),p.displaySampleRate()));if(dragGain)p.set(nodeId("gain"),juce::jlimit(-48.f,dragShape==int(sp::Shape::Notch)?0.f:24.f,24-(e.position.y-graph.getY())/graph.getHeight()*72));repaint();}
 void mouseUp(const juce::MouseEvent&)override{endDrag();}
 void visibilityChanged()override{if(!isVisible())endDrag();}
